export function advanceDirectWalk(position,target,distance,walkable){
 const p={x:position.x,z:position.z};
 if(!target||![target.x,target.z].every(Number.isFinite))return{...p,done:true,blocked:false};
 const dx=target.x-p.x,dz=target.z-p.z,length=Math.hypot(dx,dz);
 if(length<.001)return{...p,done:true,blocked:false};
 if(!Number.isFinite(distance)||distance<=0)return{...p,done:false,blocked:false};
 const travel=Math.min(distance,length),steps=Math.max(1,Math.ceil(travel/.08));
 for(let i=1;i<=steps;i++){
  const t=travel*i/steps/length,x=position.x+dx*t,z=position.z+dz*t;
  if(!walkable(x,z))return{...p,done:true,blocked:true};
  p.x=x;p.z=z;
 }
 return{...p,done:travel===length,blocked:false};
}
