import {NORTH_MODELS} from './north-landmark-plan.js';

export const MAP_COLORS={ground:'#e3dccb',road:'#778386',sidewalk:'#d6d4c6',alley:'#ded4bf',shop:'#b1a38b',landmark:'#ccb996',outline:'#7c7564',green:'#8ca175'};
const compound=new Set(['palace','library','cathedral','arts','central',...NORTH_MODELS]);

export function buildingMapAreas(buildings,collisions){
 const byOwner=new Map();
 for(const part of collisions){if(!byOwner.has(part.owner))byOwner.set(part.owner,[]);byOwner.get(part.owner).push(part);}
 return buildings.flatMap(building=>{
  if(building.siteId)return[];
  const kind=building.model==='shop'||building.lots?'shop':'landmark',owner=building.id;
  // 시장 블록의 외곽 상자는 빈 골목까지 포함하므로 개별 건물만 표시.
  if(building.lots)return building.lots.map(lot=>({owner,kind,points:footprint(lot),holes:[]}));
  const parts=compound.has(building.model)&&byOwner.get(owner);
  const areas=parts?.length?unionAreas(parts.map(part=>({points:footprint(part)}))):[{points:footprint(building),holes:[]}];
  return areas.map(area=>({...area,owner,kind}));
 });
}

let cached;
export function getMapBuildingAreas(){return cached??=buildingMapAreas(cityBuildings,collisionFootprints);}
