 function blueBuilding(p,f){
  const front=p.d/2,base=p.base||0;
  // 수평 돌림띠·모서리 돌쌓기·깊은 창틀을 사방에 유지한다.
  for(const yy of [base+.2,base+p.h*.47,base+p.h-.2]){
   block(0,yy,0,p.w+.28,.18,p.d+.28,'#c0bba6',f);
   for(const z of [-front-.19,front+.19])line([[-p.w/2,yy-.1,z],[p.w/2,yy-.1,z]],.028,'#928f80',f);
  }
  for(const sx of [-1,1])for(const sz of [-1,1])for(let yy=.8;yy<p.h;yy+=.55)micro(block(sx*(p.w/2-.22),base+yy,sz*(front+.06),.65,.43,.18,'#d1cbb6',f));
  const cols=p.oldMain?7:p.reception?5:4;
  for(const side of [-1,1]){
   const ff=group('blue-house-stone-facade',0,side*(front+.08),side<0?Math.PI:0,0,f);
   for(let i=0;i<cols;i++)for(let row=0;row<2;row++){
    const x=((i+.5)/cols-.5)*(p.w-2);if(p.oldMain&&side===1&&Math.abs(x)<3.3)continue;
    stoneWindow(x,base+p.h*(row?.72:.23),.02,p.oldMain?1.4:1.15,2.1,ff,p.oldMain&&row===1);
   }
  }
  for(const side of [-1,1]){const ff=group('blue-house-side-facade',side*(p.w/2+.07),0,side*Math.PI/2,0,f);for(const z of [-p.d*.28,0,p.d*.28])for(const yy of [base+2,base+6])if(yy<p.h-.5)stoneWindow(z,yy,0,1.1,1.8,ff);}
  if(p.oldMain){
   const ff=group('old-main-centre-stonework',0,front+.49,0,0,f);
   for(const x of [-2.4,0,2.4])stoneWindow(x,6.4,0,1.1,2.2,ff,true);
   block(0,3.62,front+2.1,9.3,.23,6.7,cream,f);block(0,3.36,front+4.6,8.2,.18,.35,'#d4cbb0',f);
   for(const x of [-3.5,3.5]){block(x,.25,front+4,.95,.5,.95,'#b4ad98',f);block(x,3.16,front+4,.9,.25,.9,cream,f);}
   for(const x of [-1.24,1.24])block(x,1.62,front+.77,.14,2.95,.22,'#cfbea0',f);
   block(0,1.62,front+.78,.1,2.95,.12,'#d7cbb0',f);block(0,2.88,front+.79,2.45,.1,.15,'#d7cbb0',f);
   steps(0,front+5.3,8,.45,f);
  }else if(p.reception){
   for(const x of [-8,-4,0,4,8]){
    mesh(new T.CylinderGeometry(.65,.72,.22,12),'#cec7b1',x,.8,front+1.2,f);block(x,10.06,front+1.2,1.35,.36,1.35,cream,f);
    for(let i=0;i<8;i++){const a=i*Math.PI/4;line([[x+Math.cos(a)*.53,1.1,front+1.2+Math.sin(a)*.53],[x+Math.cos(a)*.49,9.8,front+1.2+Math.sin(a)*.49]],.025,'#b4af9d',f);}
   }
   const start=f.children.length;corniceDetails({w:p.w+.7,d:p.d+2.5,y:p.h+.2,parent:f,mesh,box:block,color:cream,spacing:.8});microChildren(f,start);
  }
 }
