 function animalPen(p,kind,f){
  const elephant=kind==='elephant',w=p.w/2,d=p.d/2;
  // 관람객 쪽 낮은 난간과 안쪽 콘크리트 해자를 분리한다.
  const ring=(radius,y)=>Array.from({length:49},(_,i)=>{const a=i*Math.PI/24;return[Math.cos(a)*w*radius,y,Math.sin(a)*d*radius];});
  const band=(outer,inner,y,color)=>{
   const a=ring(outer,y),b=ring(inner,y),positions=[];
   for(let i=0;i<48;i++)positions.push(...a[i],...b[i],...a[i+1],...a[i+1],...b[i],...b[i+1]);
   const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.computeVertexNormals();mesh(geo,color,0,0,0,f);
  };
  band(1.015,.83,.14,'#777e6b');band(1.025,.985,.48,'#c0b79d');band(.86,.82,.24,'#c7b99b');
  for(let i=0;i<48;i+=3){const a=i*Math.PI/24;line([[Math.cos(a)*w*.99,.16,Math.sin(a)*d*.99],[Math.cos(a)*w*.99,.48,Math.sin(a)*d*.99]],.02,'#8b8b77',f);}
  if(elephant){
   const shelter=group('elephant-keeper-shelter',0,-d*.65,0,0,f);block(0,1.15,0,5.5,2.3,2.3,'#a99b7d',shelter);lowRoof(6.1,2.9,2.35,.5,shelter,'#73786a');block(0,.95,1.2,1.8,1.9,.1,'#515f50',shelter);for(const x of [-.6,0,.6])block(x,.95,1.28,.06,1.9,.1,'#8c967b',shelter);
   const trough=group('elephant-water-trough',w*.58,-d*.28,0,0,f);block(0,.3,0,2.6,.6,1.3,'#a7a58f',trough);plate(0,0,2.25,.95,.62,'#78988a',trough);
   for(const [x,z] of [[-2,1],[2.5,1.4]]){const hay=mesh(new T.SphereGeometry(1,8,5),'#ae9d60',x,.2,z,f);hay.scale.set(.8,.2,.5);}
  }
  const board=group('zoo-species-information',0,d+.42,0,0,f);block(0,.87,0,3.6,1.15,.14,'#c5b696',board);
  sign(elephant?'아시아 코끼리':'사 슴',3.25,.4,0,1.16,.09,board,'#d9cba8','#535440');
  sign(elephant?'코끼리과  ·  남아시아':'사슴과  ·  숲과 초원',3.1,.23,0,.65,.09,board,'#d9cba8','#6b6b50');
  for(const x of [-1.35,1.35])block(x,.3,0,.1,.6,.12,'#6d765b',board);
 }
