   p.strokeText('바겐세일',W/2,405,W*.87);p.fillText('바겐세일',W/2,405,W*.87);
   p.strokeStyle='#a88758';p.lineWidth=3;p.beginPath();p.moveTo(115,553);p.bezierCurveTo(350,564,650,543,909,555);p.stroke();
   p.fillStyle='#463e31';p.font='700 45px "Gulim","굴림",sans-serif';p.fillText('신사복 · 숙녀복 · 아동복',W/2,638,W*.85);
   p.fillStyle='#365e68';p.font='900 54px "Batang","바탕",serif';p.fillText('미도파 백화점',W/2,728,W*.8);
