export function dressShop({building:b,group:g,box,mesh,stroke}){
 if(!b.label)return;
 const frontage=new T.Group();frontage.position.set(0,0,(b.entrySide??1)*(b.d/2+.05));if(b.entrySide===-1)frontage.rotation.y=Math.PI;g.add(frontage);
 const sign=paintedSign(b.label,b.w*.92,.82,b.awning||'#dcd3bc');sign.position.set(0,3.4,.44);frontage.add(sign);
 if(b.kind!=='market')return;
 const canopy=new T.Group();canopy.position.set(0,2.9,.85);canopy.rotation.x=.16;frontage.add(canopy);
 box(0,0,0,b.w*.94,.12,1.65,b.awning,canopy);
 for(let i=0;i<5;i++)box(-b.w*.4+i*b.w*.2,.065,0,b.w*.095,.014,1.64,'#eee3cc',canopy);
 stroke([[-b.w*.47,.07,-.825],[-b.w*.47,.07,.825],[b.w*.47,.07,.825],[b.w*.47,.07,-.825]],LINE.inner,INK,canopy);
 for(const x of [-b.w*.42,b.w*.42])stroke([[x,2.85,.25],[x,2.75,1.55],[x,2.1,1.55]],.05,'#64594a',frontage);
 if(b.roof==='flat'){box(-b.w*.18,b.h+.9,-b.d*.25,1.25,.7,1.25,'#a4a59b',g);stroke([[-b.w*.18-.62,b.h+1.26,-b.d*.25-.62],[-b.w*.18+.62,b.h+1.26,-b.d*.25-.62]],.04,INK,g);}
}

export function buildMarketHouse({building:b,group:g,mesh,box,stroke}){
 const random=seeded(80+Math.floor(b.x*7+b.z*3)),line=(p,w=.048,col=INK,parent=g)=>brushStroke(p,w,col,parent,random);
 const colors=['#d4cbb5','#ddd5c3','#c7c9bc','#d9c3b0'],color=colors[b.stall%4];
 for(const face of [{w:b.w,x:0,z:b.d/2,turn:0,front:true},{w:b.w,x:0,z:-b.d/2,turn:Math.PI},{w:b.d,x:b.w/2,z:0,turn:Math.PI/2},{w:b.d,x:-b.w/2,z:0,turn:-Math.PI/2}]){
  const f=new T.Group();f.position.set(face.x,0,face.z);f.rotation.y=face.turn;g.add(f);
  const shape=rectShape(0,b.h/2,face.w,b.h),openings=[];
  if(face.front)openings.push({x:0,y:1.55,w:b.w*.80,h:2.65,shop:true});
  const columns=Math.max(1,Math.floor(face.w/3));
  for(let i=0;i<columns;i++)openings.push({x:face.w*((i+.5)/columns-.5),y:b.h-1.45,w:Math.min(1.8,face.w/columns*.65),h:1.45});
  if(!face.front)for(let i=0;i<columns;i++)openings.push({x:face.w*((i+.5)/columns-.5),y:2.1,w:1.3,h:1.65});
  for(const o of openings){
   const hole=rectShape(o.x,o.y,o.w,o.h);shape.holes.push(hole);
   box(o.x,o.y,-.32,o.w,o.h,.05,o.shop?'#657568':'#99afad',f);
   for(const side of [-1,1]){box(o.x+side*(o.w/2+.055),o.y,-.015,.11,o.h+.20,.36,cream,f);box(o.x,o.y+side*(o.h/2+.055),-.015,o.w,.11,.36,cream,f);}
   line([[o.x-o.w/2-.08,o.y-o.h/2-.08,.18],[o.x+o.w/2+.08,o.y-o.h/2-.08,.18],[o.x+o.w/2+.08,o.y+o.h/2+.08,.18],[o.x-o.w/2-.08,o.y+o.h/2+.08,.18],[o.x-o.w/2-.08,o.y-o.h/2-.08,.18]],.045,INK,f);
   if(o.shop){
    box(o.x,o.y+o.h/2-.20,-.19,o.w,.4,.18,'#8d9488',f);for(let n=0;n<4;n++)line([[o.x-o.w/2,o.y+o.h/2-.07-n*.1,-.08],[o.x+o.w/2,o.y+o.h/2-.07-n*.1,-.08]],.020,'#595d50',f);
    for(const side of [-1,1])box(o.x+side*o.w*.27,o.y-.05,-.23,.05,o.h-.55,.10,'#d0c4aa',f);
    box(o.x,.12,.08,o.w+.25,.18,.55,cream,f);
   }else{
    box(o.x,o.y,-.08,.07,o.h,.27,cream,f);box(o.x,o.y-.16,-.08,o.w,.065,.27,cream,f);
    box(o.x,o.y-o.h/2-.08,.07,o.w+.3,.12,.43,cream,f);
   }
  }
  mesh(new T.ExtrudeGeometry(shape,{depth:.25,bevelEnabled:false}),face.front?color:'#c7c4b5',0,0,-.25,f);
  if(face.front){box(0,b.h-2.4,.03,b.w,.18,.22,'#b5ad97',f);for(let i=0;i<5;i++){const x=(random()-.5)*b.w*.8,y=.3+random()*(b.h-.5);line([[x,y,.027],[x+.25,y+.02,.027]],.018,'#b2a58e',f);}}
 }
 if(b.stall%3===0){
  const x=-b.w*.25;line([[x,b.h+.35,-2],[x,b.h+2.1,-2]],.045,'#5c655a');
  line([[x-1.4,b.h+1.7,-2],[x+1.4,b.h+1.7,-2]],.035,'#5c655a');
  for(let i=-2;i<=2;i++)line([[x+i*.45,b.h+1.7,-2.32],[x+i*.45,b.h+1.7,-1.68]],.024,'#5c655a');
 }
}

