const roadBoxes=plan.roads.flatMap(r=>r.p.slice(1).map((b,i)=>segmentBox(r.p[i],b,r.w+2*r.sidewalk+.7)));
const reserved=[...plan.landmarks.filter(p=>p.kind!=='district').map(p=>({x:p.cx,z:p.cz,w:p.w+2,d:p.d+2,turn:p.turn})),palaceGround];
let seed=1985;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
const pick=a=>a[Math.floor(random()*a.length)];
