function projectToRoad(p){
 let closest=null;for(const r of plan.roads)for(let i=1;i<r.p.length;i++){const a=r.p[i-1],b=r.p[i],dx=b[0]-a[0],dz=b[1]-a[1],t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dz)/(dx*dx+dz*dz))),point=[a[0]+t*dx,a[1]+t*dz],distance=Math.hypot(p[0]-point[0],p[1]-point[1]);if(!closest||distance<closest.distance)closest={point,distance};}return closest;
}
